182:   function validateDates() {
183:     if (!dateError) return true;
184:     const today = getTodayISO();
185:     const start = pickupDateInput.value;
186:     const end = returnDateInput.value;
187: 
188:     if (start && start < today) {
189:       dateError.textContent = "Pickup date cannot be in the past.";
190:       dateError.hidden = false;
191:       return false;
192:     }
193: 
194:     if (start && end && end <= start) {
195:       dateError.textContent = "Return date must be after the pickup date.";
196:       dateError.hidden = false;
197:       return false;
198:     }
199: 
200:     dateError.hidden = true;
201:     dateError.textContent = "";
202:     return true;
203:   }
204: 
205:   function renderMatchingCars() {
206:     if (!matchingCarsGrid) return;
207:     const category = filterCategory.value || "all";
208:     const city = filterCity.value || "";
209:     const maxPrice = Number(maxPriceSlider.value) || 160;
210:     const favIds = getFavCarIds();
211: 
212:     if (maxPriceValue) {
213:       maxPriceValue.textContent = `$${maxPrice}/day`;
214:     }
215: 
216:     const filtered = CAR_CATALOG.filter((car) => {
217:       const matchesCategory = category === "all" || car.category === category;
218:       const matchesCity = !city || car.cities.includes(city);
219:       const matchesPrice = car.rate <= maxPrice;
220:       return matchesCategory && matchesCity && matchesPrice;
221:     });
222: 
223:     if (resultsCountText) {
224:       resultsCountText.textContent = `${filtered.length} car${filtered.length === 1 ? "" : "s"} found`;
225:     }
226: 
227:     if (filtered.length === 0) {
228:       matchingCarsGrid.innerHTML = `
229:         <div class="empty-results">
230:           No vehicles match the selected filters. Try raising the max daily price or choosing All Vehicles.
231:         </div>
232:       `;
233:       return;
234:     }
235: 
236:     matchingCarsGrid.innerHTML = filtered
237:       .map((car) => {
238:         const isLiked = favIds.includes(car.id);
239:         return `
240:           <article class="vehicle-card">
241:             <div class="vehicle-visual">
242:               <span class="vehicle-badge">${car.category}</span>
243:               <button
244:                 type="button"
245:                 class="heart-btn ${isLiked ? "is-liked" : ""}"
246:                 data-fav-id="${car.id}"
247:                 aria-label="${isLiked ? "Remove" : "Save"} ${car.name} ${isLiked ? "from" : "to"} Favourite Cars"
248:                 aria-pressed="${isLiked}"
249:               >
250:                 <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
251:                   <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
252:                 </svg>
253:               </button>
254:               <img src="${car.image}" alt="${car.name} ${car.category}" class="vehicle-img">
255:             </div>
256:             <div class="vehicle-body">
257:               <div class="vehicle-title-row">
258:                 <h3 class="vehicle-name">${car.name}</h3>
259:                 <span class="vehicle-price"><strong>$${car.rate}</strong>/day</span>
260:               </div>
261:               <p class="vehicle-meta">${car.seats} Seats &bull; ${car.transmission} &bull; ${car.mileage}</p>
262:               <p class="vehicle-hubs">Available in ${car.cities.join(", ")}</p>
263:               <button type="button" class="btn btn-primary btn-book-car" data-book-car="${car.id}">Book This Car</button>
264:             </div>
265:           </article>
266:         `;
267:       })
268:       .join("");
269:   }
