271:   function saveSearchState(hasSearched) {
272:     writeJSON(KEYS.SEARCH_STATE, {
273:       pickupCity: pickupCityInput.value,
274:       pickupDate: pickupDateInput.value,
275:       returnDate: returnDateInput.value,
276:       preferredCategory: preferredCategoryInput.value,
277:       hasSearched: Boolean(hasSearched)
278:     });
