   ========================================================================== */
.site-footer {
  background-color: #0f2742;
  color: #dbe6f2;
  padding-top: 3.25rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr 1.6fr;
  gap: 2.5rem;
  padding-bottom: 2.5rem;
}

.footer-wordmark {
  display: inline-flex;
  align-items: center;
  font-size: 1.65rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 0.65rem;
}

.brand-rent-light {
  color: #ffffff;
}

.brand-ride-footer {
  color: #14b8a6;
}

.footer-tagline {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 700;
  color: #ffffff;
}

.footer-nav-columns {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
}

.footer-col-heading {
  margin: 0 0 0.85rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  color: #ffffff;
}

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.footer-links a {
  font-size: 0.92rem;
  color: #b7c8db;
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: #14b8a6;
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  padding: 1.15rem 0;
}

.footer-bottom-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.85rem;
  color: #9cb2ca;
}

.footer-bottom-inner p {
  margin: 0;
}

.footer-inline-link {
  color: #ffffff;
  text-decoration: underline;
}

/* ==========================================================================
   Shared Drawers & Modals
   ========================================================================== */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(15, 39, 66, 0.48);
  z-index: 200;
}

.fav-drawer {
  position: fixed;
  top: 0;
  right: 0;
  width: min(420px, 100%);
  height: 100vh;
  background-color: var(--bg-surface);
  z-index: 210;
  box-shadow: -10px 0 32px rgba(15, 39, 66, 0.18);
  display: flex;
  flex-direction: column;
}

.fav-drawer[hidden],
.account-modal[hidden],
.modal-backdrop[hidden] {
  display: none;
}

.drawer-header,
.account-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.1rem 1.25rem;
  border-bottom: 1px solid var(--border-subtle);
}

.drawer-title {
  margin: 0;
  font-size: 1.08rem;
  color: var(--navy-primary);
}

.drawer-close {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-page-alt);
  color: var(--navy-primary);
  font-size: 1.3rem;
  line-height: 1;
  cursor: pointer;
}

.drawer-body {
  padding: 1.15rem 1.25rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.drawer-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.7rem;
}

.drawer-section-head h3 {
  margin: 0;
  font-size: 0.96rem;
  color: var(--navy-primary);
}

.text-btn {
  background: none;
  border: none;
  color: var(--royal-accent);
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
}

.fav-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.fav-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem;
  border-radius: 12px;
  background-color: var(--bg-highlight);
  border: 1px solid var(--border-subtle);
}

.fav-item-title {
  margin: 0;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--navy-primary);
}

.fav-item-sub {
  margin: 0.15rem 0 0;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.fav-remove-btn {
  padding: 0.35rem 0.65rem;
  border-radius: 8px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-surface);
  color: var(--error-color);
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  flex-shrink: 0;
}

.fav-empty {
  margin: 0;
  font-size: 0.86rem;
  color: var(--text-muted);
}

.account-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(400px, calc(100% - 2rem));
  background-color: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-card);
  box-shadow: 0 20px 44px rgba(15, 39, 66, 0.2);
  z-index: 215;
}

.account-modal-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.profile-box {
  padding: 0.95rem;
  border-radius: 12px;
  background-color: var(--bg-highlight);
  border: 1px solid var(--border-subtle);
}

.profile-box p {
  margin: 0.25rem 0;
  font-size: 0.92rem;
  color: var(--navy-primary);
}

/* ==========================================================================
   Responsive Breakpoints
   ========================================================================== */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 860px) {
  .nav-toggle {
    display: inline-flex;
  }

  .brand-divider {
    display: none;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background-color: #ffffff;
    border-bottom: 1px solid var(--border-subtle);
    box-shadow: 0 12px 24px rgba(15, 39, 66, 0.08);
    padding: 0.85rem 1rem 1.15rem;
  }

  .primary-nav.is-open {
    display: block;
  }

  .nav-list {
    flex-direction: column;
    align-items: stretch;
  }

  .nav-link.is-active::after {
    display: none;
  }

  .split-book-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .footer-nav-columns {
    grid-template-columns: 1fr;
  }
}

